def _expression_to_sql(expression, node, context):
    """Recursively transform a Filter block predicate to its SQLAlchemy expression representation.

    Args:
        expression: expression, the compiler expression to transform.
        node: SqlNode, the SqlNode the expression applies to.
        context: CompilationContext, global compilation state and metadata.

    Returns:
        Expression, SQLAlchemy Expression equivalent to the passed compiler expression.
    """
    # pylint: disable=too-many-return-statements,too-many-branches

    if expression.is_literal_true():
        return node.sql_literal(True)

    if expression.is_literal_false():
        return node.sql_literal(False)

    if expression.is_literal_null():
        return node.sql_literal(None)

    if expression.is_literal_number():
        return node.sql_literal(expression.value)

    if expression.is_literal_string():
        return node.sql_literal(expression.value)

    if expression.is_literal_date():
        return node.sql_literal(expression.value)

    if expression.is_literal_time():
        return node.sql_literal(expression.value)

    if expression.is_literal_timestamp():
        return node.sql_literal(expression.value)

    if expression.is_literal_interval():
        return node.sql_literal(expression.value)

    if expression.is_column_ref():
        column_ref = expression.column_ref

        if column_ref.is_table_ref():
            table_ref = column_ref.table_ref

            if table_ref.is_table():
                table = context.get_table(table_ref.table_name)
                column = table.get_column(column_ref.column_name)
                return column.sql_column

        if column_ref.is_expression_ref():
            expression_ref = column_ref.expression_ref
            return _expression_to_sql(expression_ref.expression, node, context)

        if column_ref.is_column_ref():
            return _expression_to_sql(column_ref.column_ref.expression, node, context)

    if expression.is_function_call():
        function_call = expression.function_call
        return _function_call_to_sql(function_call, node, context)

    if expression.is_cast():
        cast = expression

